import{_ as r,a,b as l}from"./chunks/07709f279ee8267bb3a9.Ct-XPu7T.js";import{_ as o,C as i,o as n,c as s,j as e,a as m,E as h,a5 as c}from"./chunks/framework.DNkHA0lr.js";const E=JSON.parse('{"title":"为什么你无法享受生活","description":"","frontmatter":{"title":"为什么你无法享受生活","originalTitle":"Why You Can’t Enjoy Life","date":"2022-07-02","originalUrl":"https://thedankoe.com/letters/why-you-cant-enjoy-life/","minutes":13,"sourceHash":"7c8296f3f7166bac20a197462ae57e2739b7358553b189f68836b896b42ede3a","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/why-you-cant-enjoy-life/"}]]},"headers":[],"relativePath":"letters/why-you-cant-enjoy-life.md","filePath":"letters/why-you-cant-enjoy-life.md"}'),u={name:"letters/why-you-cant-enjoy-life.md"};function f(d,p,g,b,y,k){const t=i("ArticleMeta");return n(),s("div",null,[p[0]||(p[0]=e("h1",{id:"为什么你无法享受生活",tabindex:"-1"},[m("为什么你无法享受生活 "),e("a",{class:"header-anchor",href:"#为什么你无法享受生活","aria-label":'Permalink to "为什么你无法享受生活"'},"​")],-1)),h(t),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/S5hQptfxnGE?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>在我成年后的大部分时间里，我都在骑摩托车。</p><p>我16岁时的第一辆“车”是一辆摩托车。（给摩托同好们提一嘴，是一辆CBR250R）。</p><p>大约一年后，我最终升级到了雅马哈R6。（一辆<em>快得多</em>的仿赛摩托）。最后我总共换过两辆。</p><p>去年，在搬到奥斯汀之前，我骑的是雅马哈R1。（<em>还要</em>快，简直……太快了……但它很适合我高大的身材）。</p><p><img src="'+r+'" alt=""></p><p>我以前的那辆R1</p><p>在德克萨斯州待了几个月后，我又心痒痒想骑车了。</p><p>我的室友（也是我的YouTube剪辑师）想学骑车。</p><p>所以我们去买了一辆二手的入门级摩托车供他学习。</p><p>他买了一辆本田Rebel 500。</p><p>我最终买下了这个尤物。</p><p><img src="'+a+'" alt=""></p><p>手里拿着咖啡杯（必须的）</p><p>现在，关于骑Bobber（复古巡航车）和骑超跑有<strong>多大</strong>的区别，我可以跟你聊上一整天，但那不是我们今天要学的东西。</p><p>（我保证，很快你就会明白我为什么提摩托车了）。</p><h2 id="学习的重要性" tabindex="-1">学习的重要性 <a class="header-anchor" href="#学习的重要性" aria-label="Permalink to &quot;学习的重要性&quot;">​</a></h2><p>我对现代教育体系有些意见。</p><p>别误会……它也有一些很棒的方面——<em>在社会如何运作这个问题上，每个人的认知应该保持在同一频道。</em></p><p>但如果说到按照自然法则生活？</p><p>对于帮助人们发现、了解他们关心的事物，并将其发展为事业来说，它是一个极其糟糕的解决方案。</p><p>现代教育体系违背了我们为求生而生的心理机制。</p><p>它逼着我们去“学习”、背诵，然后将我们训练成去干一份与我们花时间学习和背诵的内容毫无关系的工作。</p><p>另一方面……大众教育将永远无法跟上以指数级速度持续进化的数字经济。</p><p>只有那些懂得如何追随好奇心、快速学习并变得“不依赖工具”的人，最终才能脱颖而出。</p><p>通过顺应你的天性——你那为求生而生的大脑——你将开始从中获益。</p><h3 id="学习是你如何在人生这场游戏中变得更加敏锐、清醒和熟练的途径。" tabindex="-1"><strong>学习是你如何在人生这场游戏中变得更加敏锐、清醒和熟练的途径。</strong> <a class="header-anchor" href="#学习是你如何在人生这场游戏中变得更加敏锐、清醒和熟练的途径。" aria-label="Permalink to &quot;**学习是你如何在人生这场游戏中变得更加敏锐、清醒和熟练的途径。**&quot;">​</a></h3><p>当你第一次开始玩一款游戏时，你需要学习：</p><ul><li>游戏规则</li><li>机制与操作</li><li>如何赢下游戏</li></ul><p>你对这款游戏会有多好玩感到好奇。</p><p>你看完教程视频，或者阅读规则手册。</p><p>你作为一个1级玩家测试自己的极限，并很快意识到自己还有很多活要练。</p><p>你开始问自己问题：</p><ul><li>这款游戏适合我吗？</li><li>它真的值得我花时间吗？</li><li>我玩这个真的会觉得开心吗？</li><li>我的朋友们在玩这款游戏吗？</li><li>世界上有多少人在玩这款游戏？</li><li>这会消耗多少时间、金钱和其他资源？</li></ul><p>提出问题是你决定是否值得将这项新活动引入你生活的方式。</p><p>你还有其他事情要忙，不是吗？</p><p>你还有日常安排、生活方式、社交活动、习惯、杂事以及其他可能会因为持续玩这款游戏而受到影响的事情。</p><p>如果玩那款特定的游戏没有被认为比你正在玩的其他游戏更“有趣”或更有“价值”，你凭什么要把它变成你生活中的常态？</p><p>这就是很多人掉队的地方。</p><p>他们在还是1级的时候就不玩了。</p><h3 id="学习是你发现生活之深度的途径。" tabindex="-1">学习是你发现生活之深度的途径。 <a class="header-anchor" href="#学习是你发现生活之深度的途径。" aria-label="Permalink to &quot;学习是你发现生活之深度的途径。&quot;">​</a></h3><p>当你刚开始学习一款游戏（或在生活中尝试新事物）时，你可能并不喜欢它。</p><p>此时此刻你可能还无法理解它。</p><p>也许你“讨厌”星期天陪妻子去逛古董店。</p><p>并不是你真的讨厌它。而是你不懂它。</p><p>对你来说，这不是游戏，而是麻烦。</p><p>你眼中看到的只有那些在你的生活中<em>毫无用处</em>的无聊老古董。</p><p>然而，对你妻子来说，买古董是一个有趣的游戏，而且她的段位很高。</p><ul><li>她很享受在古董店里努力寻找“蒙尘明珠”的过程</li><li>她了解历史，这让她能够欣赏这些古董</li><li>她的父亲曾是个木匠，当她看到摇椅时，就会唤起对父亲的回忆</li></ul><p>她充满<em><strong>好奇（curious）</strong></em>，想深入探索这款游戏的内在运作机制。</p><p>通过经验，她对如何玩这款游戏拥有<em><strong>清晰的认知（clarity）</strong></em>。</p><p>她将这款游戏所呈现的内容与过去的或其他潜在的体验建立了<em><strong>连接（connections）</strong></em>。</p><p>她在脑海中虚构了一个<em><strong>挑战（challenge）</strong></em>，以便在那一天投入到游戏中。</p><p>她提升了自己的<em><strong>觉知（consciousness）</strong></em>，看到了游戏所呈现的相互交织的联系网。</p><p>但你……你甚至连玩都没开始玩。你不把它当成一款游戏。你把注意力死死盯在冰山一角上，并想当然地以为水面下的一切都毫无用处。</p><p>你没有给自己机会去找到你的“为什么”。</p><p>像这样做的次数多了，你连生活本身的冰山一角都无法看穿。那将是多么肤浅的存在。</p><p><em>你会发现，自己甚至还没出新手教程就已经准备好退出了。</em></p><p>在1级时，你只能假设或预测上面级别里存在什么。</p><p>在100级时，你就能对下面的级别一览无余了。</p><h2 id="随心所欲的艺术" tabindex="-1">随心所欲的艺术 <a class="header-anchor" href="#随心所欲的艺术" aria-label="Permalink to &quot;随心所欲的艺术&quot;">​</a></h2><p>每当我谈论“做你想做的事”时，总会得到同样的回应。</p><p><em>“你的意思是如果我想跳桥我也应该去跳？？？”</em></p><p><em>“你的意思是如果我想成为下一个希特勒，我也应该去做吗？”</em></p><p><em>“你的意思是如果人们变成杀人狂魔也没关系吗？！？！”</em></p><p>他妈的醒醒吧。消停点。带点常识，批判性地想想你到底在说什么。</p><p><em>这就引出了有觉知的生活和无意识的生活之间的区别。</em></p><p>如果你清醒地意识到“成为下一个希特勒”会带来的广泛影响，你根本不会想去做。</p><p>如果你非要去做，很好。这就是你察觉自身盲点并努力改变它们的方式。</p><p>如果你能觉知到你不道德的行为，以及它是如何打破集体系统平衡的，你就会努力去改变它们。</p><p>你会<em>想要</em>改进……如果你是有觉知的话。</p><p>Koe Letter 中场提醒：<a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者可以在这里花5美元加入 Modern Mastery</a>。MM 包含170多个生活和商业策略、现场培训，以及由那些建立了可持续且充满热情的一人企业（one-person business）的人所提供的循序渐进路线图。</p><h3 id="做你想做的事-关乎于顺应自然法则去生活。" tabindex="-1">做你想做的事，关乎于顺应自然法则去生活。 <a class="header-anchor" href="#做你想做的事-关乎于顺应自然法则去生活。" aria-label="Permalink to &quot;做你想做的事，关乎于顺应自然法则去生活。&quot;">​</a></h3><p>从心理学的角度来看，这已经被研究得很透彻了。</p><p>我脑海中浮现出我最喜欢的两个模型。</p><p>史蒂芬·科特勒（Steven Kotler）的5大内在驱动力和米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）的心流（flow）模型。</p><p>我们之前已经谈过很多次了，所以我就不赘述了。</p><p>简而言之，有一些特定的方法可以操控你的注意力或重塑你的专注度，从而获得更极致的体验。</p><p>多巴胺、肾上腺素和去甲肾上腺素等化学物质会喷涌入你的大脑，以此来奖励你那些源自天性的追求。</p><ul><li>发展你的技能树</li><li>精进你的手艺</li><li>追求<em>你</em>的愿景</li><li>为<em>你</em>的目标努力</li><li>遵循一套价值观生活</li><li>活在当下</li><li>为生存而狩猎（创业）</li><li>运用你的创造力（大自然是有创造力的）</li><li>提升你的觉知水平（游戏经验值）</li></ul><p>每个人内心都有一股“牵引力”，驱使自己去追求更高版本的自我。</p><blockquote><p>唯一比追求最高版本的自己更痛苦的事，就是不去追求最高版本的自己。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1357983425760817154?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2021年2月6日</a></p></blockquote><p>当你追随你的好奇心、满足你的基本需求、获得一定程度的地理自由，并不断取得进步时——你会在心理上得到奖励。</p><p>那。感觉。真好。</p><p>冲出挣扎的泥沼。</p><p>征服挑战。</p><p>在不断展开的人生故事中赢得战斗。</p><p>到达山顶。</p><p>感受一首歌曲在副歌爆点（drop）时的能量。</p><p>它们全都是一样的。</p><p>推与拉。无为。阴与阳。</p><p>生命的循环、篇章和阶段。</p><p>生命是对自然的模仿，顺应它吧。</p><p>换句话说：</p><p>系统是被操纵的，所以你要去了解这个系统，这样你才能在其中游刃有余地走向最优解。</p><p>别怪玩家，要怪就怪这游戏。</p><p>（划掉这句，别怪这游戏，要<em>欣赏</em>它）</p><h2 id="生活享受五要素-the-life-enjoyment-5" tabindex="-1">生活享受五要素（The Life Enjoyment 5） <a class="header-anchor" href="#生活享受五要素-the-life-enjoyment-5" aria-label="Permalink to &quot;生活享受五要素（The Life Enjoyment 5）&quot;">​</a></h2><p>说回摩托车。</p><p>我一直在密切关注我室友是如何学习骑摩托车的。</p><p>在我注意到他的好奇（curiosity）和认知清晰（clarity）阶段后——我开始注意到</p><p>这篇邮件订阅号原本是打算写关于“学习”的。</p><p>我（就在此时此刻）决定转变方向，谈谈“享受”（学习带来的结果）。</p><p>我开始构思一个与“创造力金字塔”完美契合的元概念。</p><p>它结合了我在探寻享受生活时发现的，存在交集的灵性、心理学和哲学教导。不仅是偶尔享受，而是随时随地享受。前提是，只要你理解了该系统的各个组成部分。理解了这场游戏的方方面面。</p><p>我称之为生活享受五要素（LE5）。</p><p><img src="'+l+'" alt=""></p><p>所有五个代表享受的“C”既是<em>工具</em>，也是<em>信号</em>。</p><p>你可以使用并组合它们来增加你对日常生活的享受感。</p><p>或者，当你在做自己真心喜欢的事情时，你可以觉察到它们的存在。</p><p>这让我想起埃克哈特·托利（Eckhart Tolle）的做事的三种模式：</p><ol><li>接纳（Acceptance）</li><li>享受（Enjoyment）</li><li>热情（Enthusiasm）</li></ol><p>它们是很好的<em>工具</em>，让你无论身处何种境遇都能安然自处——但也仅此而已……</p><p>每一种情况都会带来截然不同的变量。</p><p>我喜欢埃克哈特，他的三种模式对我帮助很大，但不仅限于此。</p><p>我做这个的目的是在他的作品（以及其他人的作品）基础上进行构建和创新，从而提出一个更强大的概念。一个能让你觉察到<a href="https://thedankoe.com/what-mushrooms-taught-me-about-life-and-business/" target="_blank" rel="noreferrer">生活所能提供的深度和机遇</a>的概念。</p><p>LE5 不是线性的，它们顺其自然地发生。不分先后顺序。</p><p><strong>好奇心（Curiosity）</strong></p><p>你感到内心被<em>牵引</em>着去做什么？</p><p>当你感觉到这种牵引时，出现了哪些限制性信念？</p><p>在此刻，停下来质疑。</p><p>不要让你那猴子般的大脑<em>认为</em>你的生存受到了威胁。</p><p><em>一种信念的消亡并不等同于死亡本身——即使那感觉诡异地相似。</em></p><p>质疑是你开辟新的心智路径去探索的方法。</p><p>质疑是你通过钻进无限的兔子洞来扩展觉知的方法。</p><p>质疑是你决定下一步需要自我学习什么内容的方法。</p><p>这在一开始很难，但通常会被以下这个问题催化：</p><p>“如果……会怎样？”</p><p>如果我学了那门技能会怎样？</p><p>如果我不计代价去旅行会怎样？</p><p><a href="https://thedankoe.com/the-future-of-work-will-be-play/" target="_blank" rel="noreferrer">如果我决心创办那家企业会怎样？</a></p><p>当我们出门去买摩托车时，我们沉浸在各种不同的型号、它们的用途以及微小的差异中。</p><p>我们两个都充满了好奇。</p><p>如果我们有了这种新的交通工具，我们的日子会变成什么样？</p><p>那引发了许多其他的问题，这些问题开始与 LE5 的其他工具联系起来。</p><p>正如你所猜想的，这打开了一个值得探索和体验的新世界（不仅仅是在路上）。</p><p>我们结识了有机车的新朋友，并在奥斯汀有效地扩大了我们的高层次人脉网络。</p><p>我们感到有种冲动去探索乡间小路，走进大自然。</p><p>这样的例子不胜枚举。</p><p><strong>清晰度 (Clarity)</strong></p><p>大多数现代问题的原因都归结于清晰度。</p><p>焦虑、不确定性、固定型思维模式、思想封闭以及其他诸多问题，都是由于缺乏清晰度造成的。</p><blockquote><p>你想要什么（目标）\\</p><p>如何实现它（清晰度）\\</p><p>为什么想要实现它（意图）\\</p><p>当这三件事水到渠成时，你的行动选择就会变得顺理成章。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1467865674932445194?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">December 6, 2021</a></p></blockquote><p>这值得写一整篇文章来探讨，并且它是<a href="https://thedankoe.com/how-to-create-a-life-of-meaning-money-impact-as-fast-as-humanly-possible/" target="_blank" rel="noreferrer">创造金字塔 (The Creation Pyramid)</a>、<a href="https://thedankoe.com/how-to-make-money-as-a-creative-on-the-internet/" target="_blank" rel="noreferrer">广义上的创造力 (creativity in general)</a> 以及<a href="https://thedankoe.com/how-to-copy-your-way-to-success-instead-of-mediocrity/" target="_blank" rel="noreferrer">智能模仿 (Intelligent Imitation)</a> 的支柱。</p><p>就机车而言，过程是这样的：</p><ul><li>沉浸</li><li>模仿</li><li>创新</li></ul><p>我的编辑 Devan 和我一起买了机车，他在以下几方面派上了我的用场：</p><ul><li>教育 —— 我带他过了一遍玩机车游戏的教程（骑行的基础知识、机械原理和/或基本功）。</li><li>教练 —— 我<strong>在</strong>他骑行<strong>时</strong>指出了他的盲区。我帮他在问题出现时将其解决。</li><li>资源 —— 我给他提供了其他可供学习的“导师”和可供阅读的材料，以加快他的学习速度。</li></ul><p>无论你是在学习一项新技能，还是在艰难应对某项具体任务……</p><p>清晰度归根结底在于结构、信息和臣服。</p><p>信息非常丰富，甚至可能令人不知所措，但这却是必要的。</p><p>将这些信息结构化（或者说让意识变得井然有序），就是你开始“勾勒拼图轮廓”的方式。</p><p>臣服与休息<em>通常</em>能将一切拼凑完整。</p><p>就像一个作家头脑风暴出15个标题后，放下笔，去泳池边躺着休息（这确实是常态，大多数作家的大部分工作都是在休息时完成的）。</p><p>又或者当程序员怎么也找不出一个bug时，却在洗澡时灵光一现，想出了完美的解决方案。</p><p>这同样适用于机车，但在面临更长期的投入时，“臣服”的一面就会发挥作用。比如创办你的企业、提升自我、充分利用生活等等。</p><p><strong>连接 (Connection)</strong></p><p>在心理学中，有一种现象叫做模式识别。在自我发展的过程中，还有一个“建构意识 (construct aware)”阶段，以及整体的系统思维。</p><p>连接源于拉开距离、纵观全局，以及识别模式、模型、建构和内在联系的能力。</p><p>这最好被描述为“啊哈！”时刻（或一系列这样的时刻）。</p><p>与好奇心一样，连接能提升大脑中的多巴胺水平。</p><p><em>它能引发兴奋感。</em> 它让你想要分享你正在学习的东西。大多数时候，你会忍不住告诉所有人你的新机车，以及你对它了解的一切。</p><p>参照 Steven Kotler 的5个内在驱动力，连接也可以放在<em>目标与激情</em>的视角下来看。</p><p>当你把你正在学习的知识与现实世界中具有实用价值的其他事物连接起来时，你就会开始为这项新技能所承载的目标培养出激情。（比如解决世界上的某个重大问题、创办一家企业，或者直接应用到你当下的生活中）。</p><p><strong>挑战 (Challenge)</strong></p><p>挑战是被编码在系统之中的。</p><p>挑战是把你推入心流的东西。</p><p>挑战是消除无聊的利器。</p><p>作为一个社会，我们如此害怕接受新的挑战，因为它们威胁到了我们已经习惯的舒适区。</p><p>如果你的工作、生活或自我没有持续不断地给你带来挑战，我敢保证你的生活不会有趣。我也敢保证你不会取得多少进步。</p><p>这再次凸显了持续自我反思和设定新目标的重要性。</p><ul><li>设定一个具有挑战性的目标</li><li>通过将其分解为更小的目标来获得清晰度</li><li>带着意图行动，让你生活的方方面面（思想、身体、精神、业务）与这些目标保持一致。</li></ul><p>如果你感到焦虑或开始过度思考，你需要清晰度。你需要学习、实践和教导他人，以此来提升你围绕该目标所具备的技能。</p><p>如果你感到无聊或无法全神贯注于手头的任务，你需要设定与你技能相匹配的新目标。</p><p><strong>意识 (Consciousness)</strong></p><p>我们将在接下来的几周里更多地探讨意识。</p><p>意识关乎深度与欣赏。即<em>爱</em>。</p><p>现在，试着开始看透表面。</p><p>接受<em>挑战</em>，带着<em>好奇心</em>去理解任何给定情况所呈现出的所有<em>连接</em>（这样你就能获得<em>清晰度</em>）。</p><p>虽然大多数人把机车看作是一台毫无意义的死亡机器——但你可以有意识地选择看透这一点，打破你对生活中无意识的、条件反射式的情绪反应。</p><p>潜得更深一点。</p><p>欣赏制造那台机车所经历的完整过程。</p><p>欣赏它为骑行者带来的种种机遇。</p><p>欣赏人们所选择参与的这场游戏。</p><p>通过将你看到的事物剖析成更小的部分来寻求理解。然后进一步深挖剖析。</p><p>说真的，停下你手中的事，想一想机车，开始向下剖析，向上建构。</p><p>用你的头脑，把机车剖析成各个零件，思考这些零件从哪里来，有哪些人参与其中，然后不断深挖，直到你触及我们用来构建物理材质的基本元素。</p><p>用你的头脑，建构一个如果有机车介入，将有助于实现你愿景的潜在现实。你能结识新朋友吗？你能把这变成生活中的新爱好吗？</p><p>如果你受制于那些让你思想封闭狭隘的无意识思维模式，你是无法做到这一点的。</p><p>在你的日常生活中，继续这种剖析与建构的过程。</p><p>你可以对任何事物这样做。（甚至是你正在看的屏幕）。任 何 事 物。</p><p>你以为我是怎么<em>创造</em>内容的？</p><p>你以为我是怎么通过非传统的方法<em>创造</em>收入的？</p><p>你以为人们一般来说是怎么<em>创造</em>的？</p><p>暂停，深潜，然后欣赏。</p><p>提升你的意识水平。</p><p>剖析与建构。</p><p><em>思考</em>。</p><p><strong>利用我们刚才探讨的一切，你可以运用 LE5 在跨领域的环境中识别、理解并解决问题。</strong></p><p>这很难理解，除非你亲身体验过。</p><p>我的建议：</p><ul><li>将 LE5 图表保存到你的手机上。</li><li>研究它的组成部分，让你的好奇心自由驰骋。（剖析与建构 —— 即创造）</li><li>当你在学习时，开始留意这个概念的不同层面。</li><li>留意你的感受，并去质问自己为什么会有这样的感受。</li></ul><p>这将让你能够在更深的层次上理解自己，并开始复制那些结果。</p><p>当你发现自己心情不好时，善加利用 LE5：</p><ul><li>质问自己为什么心情不好（好奇心）</li><li>设定一个扭转坏心情的目标（挑战）</li><li>逆向拆解它，这样你就知道该学些什么（清晰度）</li><li>在学习的过程中，观察随着你的新发现而填满大脑的兴奋感（兴奋感）</li><li>在整个过程中保持有意识的状态。</li></ul><p>这是一个庞大的话题，我们将继续去应用、剖析、建构和理解。</p><p>朋友们，我们下次见，</p><p>—— Dan Koe</p><p><strong>本周动态</strong></p><p>我上传了一期播客，概述了意识及其在创造力中扮演的角色。</p><p><a href="https://open.spotify.com/episode/3LSoJtQQHPOWQvbYfLARxc?si=8edc405b3d634b19" target="_blank" rel="noreferrer">点击这里收听。</a></p><p>一部名为《为什么你不会改变（如何重塑自我）》的新 YouTube 视频刚刚上线。</p><p><a href="https://youtu.be/QBESNoCeZWY" target="_blank" rel="noreferrer">点击这里观看。</a></p><p>在 Modern Mastery 中，我上传了我构建高利润数字产品的简单直观的流程。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">点击这里支付 5 美元加入。</a></p><hr><p><a href="/en/letters/why-you-cant-enjoy-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',217))])}const q=o(u,[["render",f]]);export{E as __pageData,q as default};
